/*
 * What Gemini can ask the app for on Android (A-274).
 *
 * Android 16 lets an assistant call functions an app declares ("AppFunctions").
 * The functions are Kotlin in `plugins/gemini/KampusFunctions.kt`; this plugin
 * puts them into the generated Android project together with what Google's
 * library needs around them:
 *
 * - the library and its code generator (KSP) in the app's Gradle files,
 * - the service Android binds to, in the manifest (the class itself is
 *   generated by the library from the Kotlin file),
 * - one sentence that tells an assistant what the app is for.
 *
 * On phones older than Android 16 none of this is used: the system never
 * looks for the service.
 */
const fs = require("fs");
const path = require("path");

const {
  AndroidConfig,
  withAndroidManifest,
  withAppBuildGradle,
  withDangerousMod,
  withProjectBuildGradle,
} = require("expo/config-plugins");

/** Google's library, androidx.appfunctions. */
const LIBRARY = "1.0.0";
/** The package the Kotlin file declares; the generated service lives there too. */
const PACKAGE = "center.kampus.app.functions";
const SERVICE = `${PACKAGE}.KampusAppFunctionService`;
/** `appFunctionXmlFileName` in the Kotlin file, with `.xml`. */
const FUNCTIONS_FILE = "kampus_app_function_service.xml";

const KSP_CLASSPATH = (version) =>
  `    classpath("com.google.devtools.ksp:symbol-processing-gradle-plugin:${version}")`;

/** The root `build.gradle` with the code generator's plugin beside Kotlin's. */
function addGeneratorPlugin(gradle, kspVersion) {
  if (gradle.includes("symbol-processing-gradle-plugin")) return gradle;
  const kotlin = /^( *)classpath\(kotlinVersion \? .*\n/m;
  if (!kotlin.test(gradle)) {
    throw new Error("with-gemini-functions: no Kotlin classpath line in the root build.gradle");
  }
  return gradle.replace(kotlin, (line) => `${line}${KSP_CLASSPATH(kspVersion)}\n`);
}

/** The app's `build.gradle` with the library and its generator. */
function addLibrary(gradle) {
  if (gradle.includes("androidx.appfunctions")) return gradle;
  const kotlin = 'apply plugin: "org.jetbrains.kotlin.android"\n';
  if (!gradle.includes(kotlin)) {
    throw new Error("with-gemini-functions: app/build.gradle does not apply the Kotlin plugin");
  }
  const react = '    implementation("com.facebook.react:react-android")\n';
  if (!gradle.includes(react)) {
    throw new Error("with-gemini-functions: app/build.gradle has no react-android dependency");
  }
  return gradle.replace(kotlin, `${kotlin}apply plugin: "com.google.devtools.ksp"\n`).replace(
    react,
    `${react}
    // What Gemini can ask the app for (plugins/with-gemini-functions.js).
    implementation("androidx.appfunctions:appfunctions:${LIBRARY}")
    ksp("androidx.appfunctions:appfunctions-compiler:${LIBRARY}")
`,
  );
}

function escapeXml(text) {
  return text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

/** What the app is for, in the words an assistant reads before it chooses a function. */
function appMetadata(instructions) {
  return `<?xml version="1.0" encoding="utf-8"?>
<AppFunctionAppMetadata
    xmlns:appfn="http://schemas.android.com/apk/androidx.appfunctions"
    appfn:instructions="${escapeXml(instructions)}" />
`;
}

/** The manifest's `<application>` with the service and the pointer to the app's description. */
function declareService(application) {
  const services = (application.service || []).filter((s) => s.$["android:name"] !== SERVICE);
  application.service = [
    ...services,
    {
      $: {
        "android:name": SERVICE,
        "android:permission": "android.permission.BIND_APP_FUNCTION_SERVICE",
        "android:exported": "true",
        "tools:targetApi": "36",
      },
      property: [
        {
          $: {
            "android:name": "android.app.appfunctions.schema",
            "android:value": "app_functions_schema.xsd",
          },
        },
        { $: { "android:name": "android.app.appfunctions.v2", "android:value": FUNCTIONS_FILE } },
      ],
      "intent-filter": [
        { action: [{ $: { "android:name": "android.app.appfunctions.AppFunctionService" } }] },
      ],
    },
  ];
  const METADATA = "android.app.appfunctions.app_metadata";
  const others = (application.property || []).filter((p) => p.$["android:name"] !== METADATA);
  application.property = [
    ...others,
    { $: { "android:name": METADATA, "android:resource": "@xml/kampus_app_metadata" } },
  ];
  return application;
}

/**
 * @param instructions one English sentence saying what the app is for.
 * @param ksp the code generator's version; it must be the one Expo pairs with the app's Kotlin.
 */
module.exports = function withGeminiFunctions(config, { instructions, ksp }) {
  config = withProjectBuildGradle(config, (mod) => {
    mod.modResults.contents = addGeneratorPlugin(mod.modResults.contents, ksp);
    return mod;
  });
  config = withAppBuildGradle(config, (mod) => {
    mod.modResults.contents = addLibrary(mod.modResults.contents);
    return mod;
  });
  config = withAndroidManifest(config, (mod) => {
    AndroidConfig.Manifest.ensureToolsAvailable(mod.modResults);
    declareService(AndroidConfig.Manifest.getMainApplicationOrThrow(mod.modResults));
    return mod;
  });
  return withDangerousMod(config, [
    "android",
    (mod) => {
      const main = path.join(mod.modRequest.platformProjectRoot, "app/src/main");
      const code = path.join(main, "java", ...PACKAGE.split("."));
      fs.mkdirSync(code, { recursive: true });
      fs.copyFileSync(
        path.join(path.dirname(module.filename), "gemini/KampusFunctions.kt"),
        path.join(code, "KampusFunctions.kt"),
      );
      fs.mkdirSync(path.join(main, "res/xml"), { recursive: true });
      fs.writeFileSync(
        path.join(main, "res/xml/kampus_app_metadata.xml"),
        appMetadata(instructions),
      );
      return mod;
    },
  ]);
};
module.exports.addGeneratorPlugin = addGeneratorPlugin;
module.exports.addLibrary = addLibrary;
module.exports.appMetadata = appMetadata;
module.exports.declareService = declareService;
module.exports.SERVICE = SERVICE;
module.exports.PACKAGE = PACKAGE;
module.exports.FUNCTIONS_FILE = FUNCTIONS_FILE;
